const input = $json;

const researcher = String(input['Researcher'] || '').trim();
const rawJobName = String(input['Job Name'] || '').trim();
const jobType = String(input['Job Type'] || '').trim();
const cpuChoice = String(input['CPU Count'] || '1').trim();
const timeChoice = String(input['Time Limit'] || '').trim();
const partition = String(input['Partition'] || '').trim();

if (researcher !== 'researcher1') {
  throw new Error('Only researcher1 is currently allowed.');
}

if (!/^[A-Za-z0-9._-]{1,50}$/.test(rawJobName)) {
  throw new Error('Job Name may contain only letters, numbers, dot, underscore and hyphen.');
}

const allowedCPUs = { '1': 1, '2': 2 };
if (!(cpuChoice in allowedCPUs)) {
  throw new Error('Invalid CPU Count.');
}

const timeMap = {
  '5 minutes': '00:05:00',
  '10 minutes': '00:10:00',
  '15 minutes': '00:15:00'
};

if (!(timeChoice in timeMap)) {
  throw new Error('Invalid Time Limit.');
}

if (partition !== 'research') {
  throw new Error('Invalid partition.');
}

const jobs = {
  'Medical Analysis': '/research/projects/medical_job.sh',
  'Hostname Test': '/research/projects/hostname_job.sh'
};

if (!(jobType in jobs)) {
  throw new Error('Invalid Job Type.');
}

return [{
  json: {
    researcher,
    jobName: rawJobName,
    jobType,
    cpus: allowedCPUs[cpuChoice],
    timeLimit: timeMap[timeChoice],
    partition,
    script: jobs[jobType],
    submittedAt: new Date().toISOString()
  }
}];

const prepared = $('Prepare Slurm Job').first().json;
const stdout = String($json.stdout || '').trim();
const stderr = String($json.stderr || '').trim();

if (!stdout) {
  throw new Error(`Slurm returned no Job ID. ${stderr}`);
}

const jobIdMatch = stdout.match(/(\d+)/);
if (!jobIdMatch) {
  throw new Error(`Could not parse Slurm Job ID from: ${stdout}`);
}

return [{
  json: {
    success: true,
    job_id: jobIdMatch[1],
    researcher: prepared.researcher,
    job_name: prepared.jobName,
    job_type: prepared.jobType,
    cpus: prepared.cpus,
    time_limit: prepared.timeLimit,
    partition: prepared.partition,
    script: prepared.script,
    submitted_at: prepared.submittedAt,
    slurm_response: stdout
  }
}];

const submitted = $('Parse Job ID').first().json;
const line = String($json.stdout || '').trim();

let state = 'SUBMITTED';
let runtime = '-';
let node = '-';

if (line) {
  const parts = line.split('|');
  if (parts.length >= 6) {
    state = parts[2] || 'SUBMITTED';
    runtime = parts[3] || '-';
    node = parts[5] || '-';
  }
}

return [{
  json: {
    ...submitted,
    state,
    runtime,
    node,
    result_path: '/research/results',
    message: `Job ${submitted.job_id} submitted successfully`
  }
}];
